                var vl = sc.layers.add(vo); vl.startTime = bt.start + bt.vo_at; vl.name = "VO " + bt.id;
                vl.inPoint = vl.startTime;                   // whole file, from its first sample (2026-10-25: 3A heard cut at the start)
                vl.outPoint = Math.min(S.dur, vl.startTime + vo.duration);
