        for (var mk2 = master.numLayers; mk2 >= 1; mk2--) if (master.layer(mk2).name === MM.layer) master.layer(mk2).remove();
        var MMo = {}; for (var mkey in MM) if (MM.hasOwnProperty(mkey)) MMo[mkey] = MM[mkey];
        if (OFF) { MMo.t0 += OFF; MMo.t1 += OFF; if (MMo.fin !== undefined) MMo.fin += OFF; if (MMo.off !== undefined) MMo.off += OFF; }
